sparql:
PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?section ?valueLabel (COUNT(DISTINCT ?paper) AS ?paperCount) WHERE {
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C121001 .
  {
    ?contribution orkgp:P181002 ?v . ?v rdfs:label ?valueLabel . BIND("RE task" AS ?section)
  } UNION {
    ?contribution orkgp:P181003 ?nlpTask . ?nlpTask orkgp:P181004 ?v . ?v rdfs:label ?valueLabel . BIND("NLP task type" AS ?section)
  } UNION {
    ?contribution orkgp:P181011 ?ds . ?ds orkgp:P181021 ?v . ?v rdfs:label ?valueLabel . BIND("NLP data abstraction level" AS ?section)
  } UNION {
    ?contribution orkgp:P181011 ?ds . ?ds orkgp:P181022 ?dt . ?dt orkgp:P181023 ?v . ?v rdfs:label ?valueLabel . BIND("NLP data format" AS ?section)
  } UNION {
    ?contribution orkgp:P181031 ?ap . ?ap orkgp:P181032 ?ann . ?ann orkgp:P181035 ?v . ?v rdfs:label ?valueLabel . BIND("Annotator identity" AS ?section)
  } UNION {
    ?contribution orkgp:P181031 ?ap . ?ap orkgp:P181041 ?aa . ?aa orkgp:P181042 ?v . ?v rdfs:label ?valueLabel . BIND("Intercoder reliability metric" AS ?section)
  } UNION {
    ?contribution orkgp:HAS_EVALUATION ?ev . ?ev orkgp:P181051 ?bc . ?bc orkgp:P181052 ?v . ?v rdfs:label ?valueLabel . BIND("Baseline comparison type" AS ?section)
  } UNION {
    ?contribution orkgp:HAS_EVALUATION ?ev . ?ev orkgp:P110006 ?v . ?v rdfs:label ?valueLabel . BIND("Evaluation metric" AS ?section)
  }
}
GROUP BY ?section ?valueLabel
ORDER BY ?section ?valueLabel
